from collections import defaultdict

def checkMirrorTree(n: int, e: int, A: List[int], B: List[int]) -> int:
    def build_tree(edges):
        tree = defaultdict(list)
        for i in range(0, 2 * e, 2):
            u, v = edges[i], edges[i + 1]
            tree[u].append(v)
        return tree

    tree_A = build_tree(A)
    tree_B = build_tree(B)

    def is_mirror(root1, root2):
        if not tree_A[root1] and not tree_B[root2]:
            return True
        if len(tree_A[root1]) != len(tree_B[root2]):
            return False
        return all(is_mirror(a, b) for a, b in zip(sorted(tree_A[root1]), sorted(tree_B[root2], reverse=True)))

    return 1 if is_mirror(1, 1) else 0
